  v = `لا يمكنك تغيير فئة حدث مُفعّل عليه خيار "تحديث الصفحة التعريفية". لتغييره، قم أولًا بتعطيل هذا الخيار من خلال إيقاف تشغيله في علامة تبويب "الصفحة التعريفية".`,
  y = `لا يمكنك تغيير فئة صفحة مبدع المحتوى الرئيسية.`,
  b = `لا يمكنك تغيير فئة تحديث الرئيسي مرتبط برسالة تسويقية.`,
  x = `تحديث اللعبة`,
  S = `أبلغ اللاعبين بالتحديثات سواء كانت كبيرة أو صغيرة، أو محتوى جديد، أو تغييرات في الوظائف، أو إصلاحات للأخطاء`,
  C = `وجّه دعوة لجمهورك للتفاعل مع المطورين والدردشة معهم والتعرّف عليهم وطرح الأسئلة.`,
  w = `أعلِم اللاعبين أن لعبتك أصبحت متاحة الآن`,
  T = `شجّع اللاعبين على متابعة لعبتك من خلال إقامة بطولة أو بث مباشر للمطورين أو مشاهير مقدمي البث المباشر`,
  E = `أكثر ما يناسب الإصلاحات والتغييرات الصغيرة التي تؤثر في مجموعة محدودة من لاعبيك.`,
  D = `أكثر ما يناسب تحديثات الميزات العادية التي تحدث أسبوعيًا أو شهريًا.`,
  O = `احفظ هذه لتحديثاتك الكبرى التي تحدث مرة كل ثلاثة أشهر أو عدة مرات في السنة.`,
  k = `أعلِن عن محتوى إضافي جديد متاح للشراء من أجل لعبتك.`,
  A = `أخبر اللاعبين بموعد الإصدار.`,
  j = `أعلِن عن تخفيض لفترة محدودة على هذه اللعبة.`,
  M = `أعلِن عن تخفيض على عناصر قد تهم اللاعبين الحاليين، على سبيل المثال: العناصر الافتراضية أو العملة الافتراضية أو المحتوى الإضافي.`,
