  F = `أعلِن أن اللاعبين سيحصلون على مكافآت أو مزايا في فترة محدودة داخل اللعبة عند إكمال مهام و/أو المشاركة في فعاليات المجتمع.`,
  I = `تحديات يومية أو أسبوعية أو شهرية أو خاصة`,
  L = `اطلب من معجبيك القيام ببعض الأنشطة للمشاركة في مسابقة. قد تكون أعمالًا فنية أو المشاركة في ورشة أو مباريات تنافسية جماعية.`,
  R = `ادعُ معجبيك للقائك شخصيًا! أو أخبرهم إذا كنت ذاهبًا إلى مكان رائع.`,
  z = `شارك جمهورك أخبارًا مهمة. هل حققت إنجازًا بارزًا؟ أم تعمل على مشروع مشوّق؟`,
