  V = `عرض مجاني لفترة محدودة لعملاء Steam لتجربة لعبتك أو محتواها الإضافي أو المحتوى داخل اللعبة. قد يكون هذا العرض عطلة نهاية أسبوع مجانية، أو نسخة تجريبية من اللعبة، أو أي شكل آخر من أشكال الوصول المحدود للمحتوى.`,
  H = `صف إطلاق الموسم الجديد أو بطاقة المعركة. عادةً ما تمتد هذه الفترة لأسابيع أو أشهر وتتضمن محتوى إضافيًا أو مزايا أو فعاليات فرعية.`,
  U = `يمكنك استخدام هذه الفئة للحديث عن لعبة أخرى ستصدرها، أو عن منصة أخرى ستصدر عليها لعبتك. هذه الفئة الوحيدة التي يمكنك استخدامها إذا كان منشورك عن لعبة مختلفة أو منصة أو متجر آخر.`,
  W = `شجّع جمهورك على لعب لعبتك معًا في وقت محدد.`,
  G = `استضف حدثًا خاصًا داخل اللعبة مع صور مؤقتة تحت عنوان الهالوين.`,
  K = `خصّص صفحة مبدع المحتوى الخاصة بك (صفحة المطور، أو الناشر، أو صفحة سلسلة الألعاب). سيتم عرض أحدث صفحة متاحة للعامة من بين هذه الصفحات.`,
  q = `أعلن عن عناصر افتراضية جديدة أو محتوى داخل اللعبة متاح للعبتك.`,
  J = `تزويد عملاء Steam بتفاصيل جديدة حول التذكرة الموسمية أو تذكرة المعركة التي أطلقتها سابقًا. من الأنسب تحديد وتيرة لتحديث المحتوى مرتبطة بفترة زمنية محددة.`,
  Y = `إصدار اللعبة أو المحتوى/الاختبار التجريبي`,
  X = `الإعلان عن موعد إصدار لعبتك، أو النسخة التجريبية، أو المحتوى الإضافي القابل للتنزيل، أو الموسم الخاص`,
  Z = `صف إطلاق المحتوى الإضافي الجديد أو الموسم أو تذكرة المعركة. أخبر العملاء بما يمكن توقعه وما إذا كان المحتوى مدفوعًا أم مجانيًا.`,
  Q = `يمكن أن تشير فعاليات البث المباشر إلى بث Steam أو إلى موقع بث خارجي. يمكنك تحديد أوقات البدء والانتهاء المجدولة. يمكن أن يظهر بث Steam في صفحة المتجر الخاص بك والصفحة الرئيسية على Steam.`,
  ne = `اختر نوع البث المباشر`,
  re = `خصم أو عرض ترويجي أو تجربة مجانية`,
  ie = `للحصول على خصومات، أو تجارب، نسخ عروض تجريبية، أو عروض ترويجية على لعبتك أو للمحتوى الإضافي للعبة، أو للمحتوى داخل اللعبة. أعلِن عن خصم على اللعبة لغير المالكين، أو أبلغ اللاعبين الحاليين بشأن الخصم داخل اللعبة.`,
  ae = `عادةً ما تكون الخصومات غير ظاهرة حتى لحظة بدء سريانها. يمكنك جدولة الخصم هنا مع الإعلان المصاحب له والتصميم الفني.`,
  oe = `اختر نوع الخصم`,
  se = `حدد موعدًا لخصم على لعبتك أو محتواك الإضافي ليظهر في متجر Steam.`,
  ce = `حدث داخل اللعبة`,
  le = `أعلن عن الفترة الزمنية التي يمكن للاعبين خلالها المشاركة في بعض الأنشطة داخل اللعبة للحصول على مكافآت أو لمجرد التواجد معًا.`,
  ue = `مزايا خاصة، أو مكافآت، أو حوافز`,
  de = `شجع جمهورك على لعب لعبتك للحصول على مجموعة معينة من المكافآت أو الجوائز.`,
  fe = `أعلن عن فعاليةٍ محدودة المدة في لعبتك. يمكن أن تمنح هذه الفعالية اللاعبين عناصر إضافية، ومكافآت، ومزايا، وجوائز، ونقاط خبرة، وما إلى ذلك. لهذه الفعاليات وقت بداية ونهاية محددين.`,
  pe = `اختر نوع الفعالية`,
