  ge = `أعلن عن تحدٍ لفترة محدودة للاعبين في لعبتك.`,
  _e = `اختر نوع التحدي`,
  ve = `%1$s فعاليات خاصة`,
  ye = `يمكنك استخدام هذا النوع من الفعاليات لإبراز لعبتك بطرق مميزة خلال هذه الفعالية. انقر على زر المعلومات أدناه لمعرفة المزيد حول كيفية استخدام هذه الفعاليات خلال %1$s.`,
