  ec = `فعاليات بطابع خاص: %1$s`,
  tc = `هالوين 2022`,
  nc = `هل تتعلق هذه الفعالية بتحديثات لعبتك بمناسبة عيد الهالوين 2022؟ إذا كنت تضيف خرائط أو هيئات أو أعمال فنية أو محتوى جديدًا إلى هذه اللعبة بمناسبة الهالوين، أو تُقيم فعاليات محدودة المدة تتضمن محتوىً مرعبًا خاصًا أو تحديات أو أنشطة مشابهة، فنودّ معرفة ذلك. نحن نفكر بطرق لعرض الفعاليات ذات الطابع الخاص بشكل أفضل لجمهور أوسع، ولكننا نحتاج أولًا أن نفهم بشكل أفضل نوع الأنشطة التي يُقيمها مطورو ألعابكم (إن وُجدت) للاحتفال بهذه المناسبة. يُرجى النقر على "تشغيل" أدناه إذا كان هذه الفعالية لها علاقة بتحديث لعبتك بمناسبة عيد الهالوين 2022.`,
  rc = `فعاليات بطابع الهالوين`,
  ic = `هل تُقيم فعالية أو تُضيف محتوىً ذا طابع هالوين؟ راجع %1$s لمعرفة المزيد حول المشاركة في Steam Scream من خلال فعالية الهالوين داخل اللعبة.`,
  ac = `وثائق فعالية Steam Scream Halloween`,
  oc = `محتوى إضافي جديد أو إضافة إلى اللعبة`,
  sc = `إضافات دائمة لطابع الهالوين إلى لعبتك`,
  cc = `أعلن عن فعالية ذات طابع هالوين محدودة المدة في لعبتك. يمكن أن تمنح هذه الفعالية اللاعبين عناصر إضافية، ومكافآت، ومزايا، وجوائز، ونقاط خبرة، وما إلى ذلك. لهذه الفعاليات وقت بداية ونهاية محددين.`,
  lc = `فئة ترشيح جوائز Steam`,
  uc = `يرجى اختيار فئة معينة ليتمكن معجبوك من ترشيح لعبتك فيها. سيتمكنون من ترشيح لعبتك لتلك الفئة مباشرةً خلال الفعالية!`,
