  Ld = `تفتقر الفعالية إما إلى وصف باللغة الإنجليزية أو اسم باللغة الإنجليزية أو كلاهما. اللغة الإنجليزية هي اللغة الأساسية أو اللغة الاحتياطية للعديد من مستخدمي Steam. ودونها، ستكون رؤية عملاء Steam للفعالية محدودة للغاية.`,
