  Oh = `المتجر: في صفحة متجر لعبتك`,
  kh = `ستظهر هذه الفعالية في صفحة متجر لعبتك في قسم "الأخبار والفعاليات".`,
  Ah = `يعكس الرقم هنا العدد التقديري للزوار لصفحة متجرك خلال الفترة التي ستظهر فيها الفعالية.`,
  jh = `المتجر: في صفحة "الألعاب المحدّثة مؤخرًا"`,
  Mh = `إذا استخدمت ميزة تحديث الظهور بعد نشر هذه الفعالية، فستظهر في صفحة "التحديثات الأخيرة" للاعبين الذين يمتلكون لعبتك أو يضيفونها إلى قائمة أمنياتهم.`,
  Nh = `الرقم هذا هو عدد المستخدمين الذين يمتلكون لعبتك أو يضيفونها إلى قائمة أمنياتهم ويمكنهم رؤيتها في صفحة "التحديثات الأخيرة".`,
  Ph = `الأخبار: على صفحة أخبار لعبتك`,
  Fh = `ستظهر هذه الفعالية في قائمة الأخبار، والتي يمكن الوصول إليها بالنقر على "عرض الأخبار ذات الصلة" من صفحة متجر لعبتك.`,
  Ih = `هذا الرقم هو مقدار حركة البيانات لصفحة الأخبار الخاصة بلعبتك.`,
