  Kh = `المكتبة: لافتة الأبرز على صفحة مكتبة لعبتك`,
  qh = `إذا وفرت صورة لافتة الأبرز، فيمكن أن تظهر فعاليتك/إعلانك تحت زر "تشغيل" في صفحة تفاصيل اللعبة الخاصة بك في مكتبة Steam.`,
