  Zh = `على صفحة الورشة`,
  Qh = `يمكنك أيضًا نشر هذه الفعالية/الإعلان في ورشة Steam الخاصة بلعبتك. لتفعيل هذه الميزة، انتقل إلى علامة التبويب "خيارات" وحدد "النشر أيضًا في الورشة". لا تظهر فعاليات/إعلانات اللعبة في قسم الورشة افتراضيًا.`,
  $h = `لافتة صفحة تخفيضات منتج Steam`,
  eg = `سيظهر شعار صفحة المنتج من %1$s إلى %2$s`,
  tg = `يمكنك إضافة لافتة ترويجية للتخفيضات في علامة تبويب "التخفيضات"، مما يسمح للألعاب المميزة بالرجوع إلى صفحة التخفيضات من خلال عرض اللافتة أعلى صفحة المنتج على Steam. يُفيد هذا عملاء Steam الذين يكتشفون خصمًا على لعبة معينة عبر البريد الإلكتروني للألعاب المضافة إلى قائمة الأمنيات أو أثناء تصفح المتجر، حيث يُتيح لهم معرفة المزيد عن فعالية التخفيضات الأوسع. تظهر هذه اللافتات من بداية التخفيضات وحتى نهايتها، أو لمدة أسبوعين، أيهما أقرب. يتم تحديد وقتي بدء وانتهاء التخفيضات في علامة تبويب "الخيارات".`,
  ng = `إشعار: إرسال بريد إلكتروني إلى اللاعبين الذين يتابعون لعبتك أو مطورها أو ناشرها`,
  rg = `يشمل ذلك جميع متابعي لصفحات المطورين والناشرين وصفحات السلاسل المرتبطة بهذه اللعبة.`,
  ig = `الروابط التالية للمطورين أو الناشرين أو أصحاب الامتيازات لا تحتوي على صفحة رئيسية مرئية. إنشاء رابط سيساعد عملاءك على فهم عروضك ويمنحهم فرصة التعرف على فعالياتك وإطلاق ألعابك الجديدة: %1$s`,
  ag = `الأخبار: جدول فعاليات مخصص للاعبين`,
  og = `ستظهر هذه الفعالية في مركز الأخبار المخصص للاعبين الذين لديهم لعبتك في مكتبتهم، أو في قائمة الأمنيات الخاصة بهم أو يتابعون لعبتك.`,
  sg = `إشعار: إرسال إشعار فوري إلى اللاعبين المشتركين`,
  cg = `عدد اللاعبين الذين اختاروا تلقي تذكير بهذه الفعالية (نزلوا قائمة تقويم خارجية أو اختاروا متابعة هذه الفعالية).`,
  lg = `اللاعبين الذين يتلقون بريدًا إلكترونيًا`,
  ug = `عدد الرسائل الإلكترونية المُقدّر التي ستتضمن هذه الفعالية. نقوم دوريًا بإنشاء قائمة مُجمّعة بالفعاليات المُستهدفة لكل عميل، وذلك بناءً على إعدادات كل عميل فيما يتعلق بتفعيل الاشتراك في الرسائل الإلكترونية وتفضيلات التواصل.`,
  dg = `اللاعبون الذين يتلقون رسالة تسويقية`,
  fg = `عدد اللاعبين المتوقع ظهور هذه الفعالية في رسالة التسويق المخصصة لهم على تطبيق Steam. هذه نافذة منبثقة تظهر عند تشغيل برنامج تشغيل Steam على سطح المكتب، وتعرض تخفيضات Steam ومعلومات شيقة عن الفعالية.`,
  pg = `تجاهل اللاعبون هذه الفعالية`,
  mg = `عدد اللاعبين الذين اختاروا صراحةً تجاهل هذه الفعالية.`,
