  _g = `مراجعة التحديث الرئيسي للرسالة التسويقية`,
  vg = `بمجرد اكتمال الفعالية وعدم الحاجة إلى أي تعديلات إضافية، يُرجى إرسالها للمراجعة لاستخدامها في رسالة تسويقية. يُمكنك نشر فعالية التحديث الرئيسي فور جاهزيته. يُرجى الانتظار لمدة تصل إلى %1$s يوم عمل للمراجعة والموافقة.`,
  yg = `أنشئ التذكرة التالية لبدء عملية المراجعة.`,
  bg = `إنشاء تذكرة التقييم`,
