  Sg = `الملخص`,
  Cg = `بدء الظهور`,
  wg = `سيظهر هذا فورًا في معظم الأماكن بمجرد النشر.`,
  Tg = `يرجى العلم أن فريق الإشراف لدينا يراجع المنشورات الجديدة حسب ترتيب نشرها. قد يكون هناك تأخير لأكثر من ساعة قبل ظهور الأخبار أو الفعاليات في مكتبة Steam. أي تعديلات على المنشورات الموجودة ستعيد منشورك إلى قائمة انتظار الإشراف.`,
  Eg = `أو استبدل محتويات الفعالية الحالية`,
  Dg = `غير شائع. يتيح لك هذا إنشاء تحديثات مؤقتة فيما يشبه مسودة فعالية، ثم استبدال محتوى موجود لفعالية منشورة بمحتوى هذه الفعالية. ستختفي هذه الفعالية، وسيحل محتواها محل الفعالية المنشورة المستهدفة. لن يتم تحديث نوع الفعالية وإعدادات الرؤية الخاصة بالفعالية المستهدفة.`,
  Og = `تم استنساخ هذه الفعالية من: '%1$s'`,
  kg = `الاستبدال في الفعالية الأصلية`,
