  jg = `ملاحظة: يجب نشر الفعالية الأصلية وجعلها مرئية. لا يمكننا استبدالها إلا بعد أن تصبح مرئية للجميع.`,
  Mg = `هذا الإجراء فوري. سيحل محل محتوى الفعالية المستهدفة وستكون مرئيةً لمستخدمي Steam على الفور. سيتم حذف الفعالية الحالية في هذا الإجراء.`,
