  Qg = `يُسمح لأصحاب البث هؤلاء بالظهور على صفحة الفعالية والمتجر الخاص بك عندما يبثون لعبتك خلال هذه الفعالية.`,
  $g = `التمهيد للبث`,
  e_ = `تم الإيقاف: تم إيقاف تشغيل خدمة بث الفيديو حسب الطلب (VOD)، وسيتم الاحتفاظ بالفيديو القديم في حال احتجنا إليه. سيُعرض هذا الفيديو في مشغل البث قبل بدء البرامج العادية. يجب أن يكون لبث الفيديو حسب الطلب أذونات عامة (منفصلة عن حالة الإصدار).`,
