  N_ = `هل سيتم منح العناصر يدويًا؟`,
  P_ = `كم من الوقت بالدقائق حتى يصبح الشخص مؤهلًا للحصول على العناصر؟`,
  F_ = `اختياري: يوفر فعالية على Steam تصف تفاصيل العناصر التي يتم الحصول عليها؛ وتعد مفيدة في فعاليات التخفيضات التي لا تعرض المحتوى الخاص بها.`,
