  L_ = `معرف فعالية العشيرة`,
  R_ = `عرض مشغلات واسعة`,
  z_ = `عند تفعيل هذا الخيار، سيتم إزالة العمودين الأيمن والأيسر من مشغل الفيديو. وهو مفيد فقط عندما يكون هناك بث واحد للفعالية وتُشتت الأعمدة الانتباه عن تجربة المشاهدة.`,
  B_ = `تفعيل وضع المشغل الواسع`,
