  G_ = `إذا كانت هناك مسابقة مرتبطة بالبث تعلن عن الفائزين عبر دردشة البث، فإن تعيين معرف الهدية سيسمح بسحب رسائل الدردشة حتى لو كانت الدردشة مغلقة، وذلك للبحث عن الإعلانات لأغراض العرض فقط.`,
