  $_ = `عند تفعيل هذه الميزة، سيظهر الإعلان في متجر Steam بدلاً من كبسولات الألعاب. يُفيد هذا الخيار عندما يُقدّم الإعلان معلوماتٍ أكثر أهميةً عن الفعالية مقارنةً بكبسولة تطبيقٍ مُحدّدة. كما يُفيد أيضاً عند بثّ ألعابٍ مُتعدّدةٍ في وقتٍ واحد، وترغب في عرض عنصرٍ واحدٍ فقط من عناصر الفعالية.`,
  ev = `قائمة السماح الخاصة بصاحب البث`,
