  av = `تعذر تحميل معلومات المستخدم`,
  ov = `إعداد اختياري يسمح بتحديد لغة معينة للبث المباشر للمشاهدين. يُفيد هذا الإعداد في حال وجود عدة مصادر بث بلغات مختلفة لهذه الفعالية، مما يُتيح لنا اختيار البث الافتراضي الأنسب للمستخدم بناءً على لغته.`,
  sv = `الأولوية`,
  cv = `ما هي أولوية هذا البث مقارنةً بفعاليات البث الأخرى؟ سيتم اختيار فعاليات البث ذات الأولوية الأعلى على الفعاليات ذات الأولوية الأقل. في حال وجود عدة فعاليات بث لها نفس الأولوية، سيتم اختيار أحدها عشوائيًا ليكون البث الافتراضي.`,
