  fy = `مسار %1$s غير مسمى`,
  py = `أضف فعاليات خصيصًا لهذا المسار. لا تُعتبر هذه الفعاليات صالحة إلا إذا تم نشرها، وبدأت وانتهت ضمن النطاق الزمني المحدد في الجدول الزمني، وتطابقت مع نوع الفعالية المسموح بها في الجدول الزمني.`,
  my = `اتفاقيات فعالية التخفيضات`,
  hy = `قبل أن يصبح بإمكانك استخدام أدوات محرر المبيعات، ستحتاج إلى الموافقة على المتطلبات التالية:`,
  gy = `أفهم أن صفحة البيع يجب أن تصف بوضوح المجموعة أو الأفراد المسؤولين عن تنظيم عملية البيع أو الغعالية.`,
  _y = `أتفهم أنه لا يمكنني ضمان مستوى معين من الظهور للمشاركين على Steam، ولا يمكنني فرض رسوم مقابل وضع إعلاناتهم داخل الصفحة.`,
  vy = `أفهم أن شركة Valve تحتفظ بالحق في تعديل صفحة البيع، بما في ذلك على سبيل المثال لا الحصر إمكانية رؤية الألعاب أو البث على الصفحة، أو النصوص أو الصور التي تصف الفعالية.`,
