  by = `أتفهم أنني قد أضيف ألعاب فقط إلى صفحة البيع التي حصلت على إذن لها من المطور أو الناشر. سيرى مطورو اللعبة أن لعبتهم مدرجة في عملية البيع الخاصة بي فور إضافتها إلى صفحتي هنا.`,
