  VS = `يمكن إدارة تسجيل الدخول الرقمي للعبتك. هذا سيمكّن إدارة إعدادات نظام مكافحة الغش و مصادقة SDK للتطبيق.`,
  HS = `إدارة الرموز التسلسلية`,
  US = `تعديل بيانات تسويق التطبيقات`,
  WS = `يمنح الإذن لتعديل بيانات صفحة المتجر ونشرها مثل وصف اللعبة وصور هوية الشعار المميزة ومقاطع الفيديو. ويشمل أيضًا إمكانية الوصول إلى أدوات التسويق مثل جولات الظهور.`,
  GS = `تعديل بيانات تعريب المتجر`,
  KS = `يمنح الإذن لتعديل أي بيانات في علامات تبويب إعدادات المتجر التي تحتوي على خانة أو أكثر يمكن تعريبها، مثل وصف المنتج والأصول الرسومية. لا يمنح الإذن للنشر أو الوصول للتسويق مثل جولات الظهور. ملاحظة: هذا جزء فرعي من وظيفة "تعديل بيانات تسويق التطبيق".`,
  qS = `دعم العناصر القابلة للتداول/ الورشة`,
  JS = `يسمح للمستخدم بعرض/ تقديم عناصر قابلة للتداول في أداة دعم إدارة هذه العناصر في موقع الشريك.`,
  YS = `مشرف العناصر القابلة للتداول/ الورشة`,
