  ZS = `إدارة التسعير والخصومات`,
  QS = `تسمح للمستخدم باقتراح تغييرات في التسعير والمشاركة في الخصومات والترقيات.`,
  $S = `بث مباشر`,
  eC = `يسمح للمستخدم ببث عروض البث المباشر الرسمية لتطبيقاتك.`,
  tC = `عرض بيانات إحصائيات التسويق`,
  nC = `يمكن عرض بيانات إحصائيات التنقل في متجر Steam والمجتمع والمنصة للعبتك`,
  rC = `إدارة المستخدمين`,
  iC = `على مستوى الناشر: هؤلاء المستخدمون يمكنهم إضافة مستخدمين آخرين وترقيتهم`,
  aC = `الصلاحية الفعلية`,
  oC = `على مستوى الناشر: يمكن لهؤلاء المستخدمين تغيير تفاصيل الدفع (على سبيل المثال، معلومات الحساب المصرفي والمعلومات الضريبية) ونقل حقوق الملكية الفكرية`,
  sC = `عرض البيانات المالية (على مستوى الناشر)`,
  cC = `على مستوى الشريك: يمكن لهؤلاء المستخدمين عرض تقارير المبيعات والبيانات المالية لجميع التطبيقات المدارة بواسطة هذا الشريك`,
  lC = `الموافقة على تمويل المحفظة`,
  uC = `هؤلاء المستخدمون يمكنهم الموافقة على معاملات تمويل محافظ العملاء.`,
  dC = `إدارة المواقع المرخصة`,
  fC = `يمكن لهؤلاء المستخدمين عرض وإدارة معلومات أماكن الموقع المرخص والتراخيص والنشاط`,
  pC = `تلقي رسائل وإشعارات Steamworks`,
  mC = `سيتم إرسال بريد إلكتروني إلى هؤلاء المستخدمين حول العروض الترويجية القادمة والأحداث المستهدفة وإعلانات الميزات الجديدة على Steam.`,
  hC = `تم إرسال دعوة إلى هذا المستخدم لتلقي إذن اتصال Steamworks، لكنه لم يقبلها بعد.`,
  gC = `تفعيل صفحة التخفيضات`,
  _C = `تتطلب صفحة التخفيضات منك تقديم العنصرين التاليين:`,
  vC = `يجب أن تختار اسم مميز سيظهر في نهاية عنوان الموقع. دون ذلك، لن يتمكن عملاء Steam من الوصول إلى صفحة التخفيضات الخاصة بك`,
  yC = `يجب تحديد تاريخ ووقت البدء والانتهاء. إذا لم يتم ضبط هذه الإعدادات بشكل صحيح، لن تعمل خاصية تتبع الإحصائيات وتصميم صفحة المنتج بشكل صحيح.`,
  bC = `وقت بدء التخفيضات`,
  xC = `وقت انتهاء التخفيضات`,
  SC = `تفعيل تحديث الصفحة الرئيسية`,
  CC = `يتطلب تحديث الصفحة الرئيسية منك تقديم اسم مميز سيظهر في نهاية رابط صفحة متجرك. سيرى عملاء Steam الصفحة الرئيسية هذه على ذلك الرابط.`,
  wC = `هل تريد تفعيل محرر صفحة البيع لهذه الفعالية؟`,
  TC = `هل تريد تفعيل الصفحة الرئيسية للتحديث لهذه الفعالية؟`,
  EC = `اختر من قائمة العناوين الافتراضية:`,
  DC = `العنوان الافتراضي غير مستعمل بسبب وجود عنوان مخصص باللغة الحالية أو باللغة الإنجليزية`,
  OC = `أو قم بالتجاوز باستخدام عنوان مخصص`,
  kC = `العناوين المخصصة المدخلة:`,
