  jC = `عرض طبقة خاصة على رأس الصفحة (على سبيل المثال، مكون مثل بيت الأشباح على Steam لعيد الهالوين 2019)`,
  MC = `عرض عنوان الفعالية ووصفه كطبقة فوق رأس الصفحة`,
  NC = `إزاحة البكسل`,
  PC = `تم تعطيل إزاحة البكسل لأن شعار صفحة البيع مُدرج. يقوم الشعار بالتعامل مع إزاحة البكسل تلقائيًا.`,
  FC = `هذا هو عدد البكسلات اللازمة لتحريك محتوى صفحة البيع للأسفل لإتاحة مساحة للعنوان والتواريخ في صورة خلفية صفحة البيع. لن نحتاج إلى تعديل هذا الإعداد إلا إذا كنا بحاجة إلى إنجاز شيء مميز للغاية.`,
  IC = `يجب أن تكون القيمة الافتراضية (والقصوى) هنا %1$s`,
