  HC = `مطلوب معرف/معرفات الحزمة`,
  UC = `عدّل تصميم الكبسولة لعرض زر "إضافة إلى المكتبة/تشغيل الآن" بدلاً من الأسعار وزر "إضافة إلى السلة".`,
