  KC = `استخدام مخطط الاشتراك`,
  qC = `لا تسمح إلا لمالكي هذه الحزم (أو أي تطبيقات من القائمة الأخرى) بمشاهدة هذه الصفحة`,
  JC = `تنبيه: خاصية البيع غير مُفعّلة في هذه الفعالية من قِبل Valve. شركة Valve هي الجهة الوحيدة المخوّلة بتفعيل خاصية البيع في النسخة التجريبية المغلقة. يُرجى التواصل مع مسؤول الاتصال الخاص بك في Valve لطلب تفعيل صفحة البيع لهذه الفعالية.`,
