  ZC = `البث/قنوات البث المباشر`,
  QC = `استخدم تبويب البث لضبط إعدادات البث الأخرى لفعالية التخفيضات هذه.`,
  $C = `تم تعطيل البث في فعالية التخفيضات هذه.`,
  ew = `استخدم تبويب البث لتفعيل البث لفعالية التخفيضات هذه. بعد التفعيل، يمكنك تخصيص سلوكه بشكل أكبر في هذه الصفحة.`,
  tw = `قم بتضمين عمليات البث المسموح بها تحديدًا فقط في تبويب "البث".`,
  nw = `بشكل افتراضي، يقوم Steam تلقائيًا بعرض أي بث مباشر مرتبط بأي لعبة تظهر في صفحة التخفيضات هذه. لا يلزم اتخاذ أي إجراء إذا كان الإعداد الافتراضي مناسبًا لهذا العرض. مع ذلك، إذا كنت ترغب في التحكم بشكل مباشر في البث الذي يظهر في صفحة التخفيضات، يمكنك تفعيل هذا الخيار واختياره يدويًا من تبويب البث.`,
  rw = `الإعدادات العامة للصفحة`,
  iw = `الدليل الرئيسي لمنشئ المحتوى`,
