  fR = `قسم الكشف الديناميكي`,
  pR = `ٌقسم الكشف الديناميكي مفيد بالتزامن مع بث الإعلانات المباشرة. يسمح للمشغل بإضافة التطبيقات/ الحزم/ الباقات المرئية في المتجر بعد أن تكون التخفيضات مرئية وجعلها تظهر في عرض عملاء Steam في الصفحة دون المطالبة بإعادة تحميل الصفحة. نوصي بوضع هذا القسم قرب مشغل عروض البث. احرص على إضافة التطبيقات المرئية فقط وإلا فستخزن صفحة المتجر حالتها المخفية في ذاكرة التخزين المؤقت ولن يكون التطبيق مرئيًا لعملاء Steam.`,
