  vR = `يُستخدم قسم الكشف الديناميكي بالتزامن مع البث المباشر للإعلانات. نوصي بوضع هذا القسم قرب مشغل عروض البث في صفحة التخفيضات. تفقّد دوريًا ما إذا كانت فعاليات Steam الجديدة قد أُضيفت إلى هذه القائمة واعرض فعاليات Steam دون مطالبة العميل بإعادة تحميل الصفحة.`,
  yR = `يُسمح بتطبيق/ باقة/ حزمة واحدة فقط وقسم كشف ديناميكي واحد للأخبار والفعاليات فقط`,
